class Solution {
    int depthX = -1, depthY = -1, parentX = -1, parentY = -1;
    int targetX, targetY;

    void dfs(TreeNode* node, TreeNode* parent, int d) {
        if (!node) return;
        if (node->val == targetX) {
            depthX = d;
            parentX = parent ? parent->val : -1;
        }
        if (node->val == targetY) {
            depthY = d;
            parentY = parent ? parent->val : -1;
        }
        dfs(node->left, node, d + 1);
        dfs(node->right, node, d + 1);
    }

public:
    bool isCousins(TreeNode* root, int x, int y) {
        targetX = x;
        targetY = y;
        dfs(root, nullptr, 0);
        return depthX == depthY && parentX != parentY;
    }
};
